// Add each GBP location here.
// Find locationId via: GET https://mybusiness.googleapis.com/v4/accounts/{accountId}/locations
// accountId looks like: accounts/123456789
// locationId looks like: accounts/123456789/locations/987654321

const locations = [
  { locationId: 'accounts/ACCOUNT_ID/locations/LOCATION_ID_1', locationName: 'Bigfoot Pest Control - Boise' },
  { locationId: 'accounts/ACCOUNT_ID/locations/LOCATION_ID_2', locationName: 'Bigfoot Pest Control - Location 2' },
  { locationId: 'accounts/ACCOUNT_ID/locations/LOCATION_ID_3', locationName: 'Bigfoot Pest Control - Location 3' },
];

return locations.map(l => ({ json: l }));

// Transform GBP review format to our sync endpoint format
const locationId = $('Locations').item.json.locationId;
const locationName = $('Locations').item.json.locationName;
const reviews = $input.item.json.reviews ?? [];

const transformed = reviews.map(r => ({
  id: r.reviewId,
  locationId,
  locationName,
  authorName: r.reviewer?.displayName ?? 'Anonymous',
  rating: r.starRating,   // 'FIVE', 'FOUR', etc. — our endpoint handles this
  text: r.comment ?? '',
  reviewDate: r.createTime,
  rawJson: r,
}));

if (transformed.length === 0) return [];
return [{ json: { reviews: transformed } }];
